class Alpha {
    void connect() {
        System.out.println("Connection established.");

        try {
            int result = 100 / 0;
            System.out.println(result);
        } catch (ArithmeticException e) {
            System.out.println("Caught in alpha; rethrowing.");
            throw e;
        }

        System.out.println("Connection terminated.");
    }
}

public class RethrowDemo {
    public static void main(String[] args) {
        Alpha alpha = new Alpha();

        try {
            alpha.connect();
        } catch (ArithmeticException e) {
            System.out.println("Handled in main.");
        }

        System.out.println("Program continues in main.");
    }
}

import java.util.InputMismatchException;
import java.util.Scanner;

public class ScannerCleanupDemo {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);

        try {
            System.out.print("Enter a number: ");
            int number = scan.nextInt();
            System.out.println("Value: " + number);
        } catch (InputMismatchException e) {
            System.out.println("Invalid input.");
        } finally {
            scan.close();
            System.out.println("Scanner closed.");
        }
    }
}

public class SleepExample {
    static void waitForThreeSeconds() throws InterruptedException {
        Thread.sleep(3000);
    }

    public static void main(String[] args) {
        try {
            System.out.println("Waiting...");
            waitForThreeSeconds();
            System.out.println("Finished waiting.");
        } catch (InterruptedException e) {
            System.out.println("Waiting was interrupted.");
        }
    }
}

public class DelayedCharacters {
    public static void main(String[] args) {
        for (char letter = 'A'; letter <= 'E'; letter++) {
            System.out.println(letter);

            if (letter < 'E') {
                try {
                    Thread.sleep(3000);
                } catch (InterruptedException e) {
                    System.out.println("Printing interrupted.");
                    break;
                }
            }
        }
    }
}

